cd /home/javad/energy-run/dx-toolkit && python3 -I - <<'EOF'
import json,re
s1=[json.loads(l) for l in open('step1.jsonl')]
s2=[json.loads(l) for l in open('step2.jsonl')]
u1={r['unit']:{x['label'] for x in r['suspicions']} for r in s1}
u2={}
for r in s2:
    if r['unit'] in u2: print('DUP unit',r['unit'])
    u2[r['unit']]={d['label'] for d in r['decisions']}
print('step1 units',len(u1),'step2 units',len(u2))
print('missing step2 units:',[u for u in u1 if u not in u2])
print('extra step2 units:',[u for u in u2 if u not in u1])
for u in u1:
    if u in u2 and u1[u]!=u2[u]: print('label mismatch',u,u1[u],u2[u])
acc=[(r['unit'],d['label'],d['root_cause']) for r in s2 for d in r['decisions'] if d['verdict']=='accepted']
